fn pending(args: ReleasePendingArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let from = args
        .from
        .as_deref()
        .map(CommitSha::parse)
        .transpose()
        .map_err(|error| callisto_graph::GraphError::ReleaseInvariant {
            detail: format!("`--from` must be a full commit SHA: {error}"),
        })?;
    let runner = CliCommandRunner;
    let workspace = load_workspace(global, &runner)?;
    let found = pending_releases(&workspace, &args.decision, args.limit, from.as_ref())?;
    match global.format {
        OutputFormat::Json => {
            let releases: Vec<_> = found
                .iter()
                .map(|release| {
                    serde_json::json!({
                        "source": release.source.as_str(),
                        "packages": release
                            .packages
                            .iter()
                            .map(|(package, version)| serde_json::json!({
                                "package": package.to_string(),
                                "version": version.render(),
                            }))
                            .collect::<Vec<_>>(),
                        "missing": release.missing,
                    })
                })
                .collect();
            write_json(&mut std::io::stdout(), &serde_json::json!({ "pending": releases }))?;
        }
        OutputFormat::Text if found.is_empty() => emit_line(NO_PENDING_RELEASES)?,
        OutputFormat::Text => {
            emit_line("Pending releases, oldest first:")?;
            for release in &found {
                let packages: Vec<String> = release
                    .packages
                    .iter()
                    .map(|(package, version)| format!("{package} {}", version.render()))
                    .collect();
                emit_line(&format!(
                    "  {}  {}  (missing: {})",
                    &release.source.as_str()[..12],
                    packages.join(", "),
                    release.missing.join(", ")
                ))?;
            }
        }
    }
    Ok(ExitCode::SUCCESS)
}

fn build_python(args: ReleaseBuildPythonArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    if global.dry_run {
        return Err(CliError::ReleaseBuildPythonDryRun);
    }
    let intent = read_intent(&global.resolve_file_arg(&args.intent))?;
    if callisto_model::python_publishes(&intent).is_empty() {
        return Err(CliError::ReleaseNoPythonPublishes);
    }
    let artifact_dir = global.resolve_file_arg(&args.artifact_dir);
    let outdir = artifact_dir.canonicalize().map_err(|source| CliError::Io {
        source,
        path: Some(artifact_dir.clone()),
    })?;
    let runner = CliCommandRunner;
    let source_workspace = load_workspace(&source_global(global, args.source_root.as_deref()), &runner)?;
    let root = source_workspace.root.clone();
    let locator = IgnoreWalkLocator::new(&root);
    let capability = validate_release_intent(&root, &locator, &runner, intent)?;
    let built = capability.build_python_distributions(&outdir)?;
    match global.format {
        OutputFormat::Json => write_json(&mut std::io::stdout(), &serde_json::json!({ "built": built }))?,
        OutputFormat::Text => emit_line(&format!(
            "Built Python distributions for {} into {}",
            built.join(", "),
            outdir.display()
        ))?,
    }
    Ok(ExitCode::SUCCESS)
}
